import { clarificationAnswerSecrets } from "./redaction.mjs";
import { validateClarificationPresentation } from "./clarification-presentation.mjs";
import { createHash } from "node:crypto";

const text = (v) => typeof v === "string" && Boolean(v.trim());
const object = (v, keys) =>
  v !== null &&
  typeof v === "object" &&
  !Array.isArray(v) &&
  Object.keys(v).length === keys.length &&
  keys.every((k) => Object.hasOwn(v, k));
const strings = (v) =>
  Array.isArray(v) && v.every((item) => typeof item === "string");
const reportKeys = [
  "status",
  "reason",
  "remainingSteps",
  "evidence",
  "questions",
  "effects",
];
const executionStatusTemplate = {
  type: "function",
  name: "execution_status",
  strict: true,
  description:
    "Report execution progress, missing caller input, or completion. Claims remain unverified. Evidence names records already saved by Runner.",
  parameters: {
    type: "object",
    additionalProperties: false,
    required: reportKeys,
    properties: {
      status: {
        type: "string",
        enum: ["needs_input", "stuck", "blocked", "complete"],
        description:
          "Use needs_input for missing caller input, stuck or blocked to describe an obstacle, and complete when execution is finished. These reports do not decide application test results.",
      },
      reason: {
        type: "string",
        description:
          'Use "Completed." for complete. Otherwise, state what prevents progress in one sentence. For uncertain effects, name the action and what is unknown.',
      },
      remainingSteps: {
        type: "array",
        description:
          "List unfinished requested work, including required checks with incomplete or conflicting observations. Action restrictions do not add checks.",
        items: { type: "string" },
      },
      evidence: {
        type: "array",
        description:
          'One exact path ID per string, copied from savedEvidenceReferences in this response chain. Do not add labels, descriptions, punctuation, or multiple paths in one string. For example: ["screen-1.png", "response-2.json"]. Never infer a filename.',
        items: { type: "string" },
      },
      questions: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["id", "question", "kind"],
          properties: {
            id: { type: "string" },
            question: { type: "string" },
            kind: { type: "string" },
          },
        },
      },
      effects: {
        type: "string",
        enum: ["known", "uncertain"],
        description:
          "Whether the effects of actions already issued are known. Unperformed checks or an unknown feature result do not make issued actions uncertain. Use uncertain when an issued action may have had an unresolved effect and repeating it could duplicate that effect.",
      },
    },
  },
};

// Evidence eligibility stays in the host ledger. Keep the provider schema stable
// as that ledger grows; never let a model-supplied path open a file.
export function createExecutionStatusTool() {
  return structuredClone(executionStatusTemplate);
}
export {
  taskBoundaryInstruction,
  executionStatusInstruction,
} from "./request-instructions.mjs";

export class ExecutionReportValidationError extends Error {}

/** Decode the report while retaining evidence labels as unverified model data.
 * Retained v1 reports may carry completedSteps. New tool output omits that
 * duplicate account; the separate recap supplies chronological observations. */
export function validateExecutionReport(value) {
  if (
    (!object(value, reportKeys) &&
      !object(value, [...reportKeys, "completedSteps"])) ||
    !["needs_input", "stuck", "blocked", "complete"].includes(value.status) ||
    typeof value.reason !== "string" ||
    !["known", "uncertain"].includes(value.effects) ||
    (Object.hasOwn(value, "completedSteps") &&
      !strings(value.completedSteps)) ||
    !strings(value.remainingSteps) ||
    !strings(value.evidence) ||
    !Array.isArray(value.questions) ||
    value.questions.some(
      (q) =>
        (!object(q, ["id", "question", "kind"]) &&
          !object(q, ["id", "question", "kind", "presentation"])) ||
        !text(q.id) ||
        !text(q.question) ||
        !text(q.kind),
    ) ||
    new Set(value.questions.map((q) => q.id)).size !== value.questions.length
  )
    throw new ExecutionReportValidationError(
      "Malformed execution_status report; execution incomplete",
    );
  if (value.status === "needs_input" && !value.questions.length)
    throw new ExecutionReportValidationError(
      "Caller input requires a question",
    );
  return structuredClone(value);
}
// Legacy presentation hints are decorative. Keep malformed originals in the
// saved model report, but do not send an unusable hint through typed transports
// or turn it into an asserted source quotation.
const questionView = (value) => {
  const { presentation, ...question } = structuredClone(value);
  if (presentation === undefined) return question;
  try {
    validateClarificationPresentation(presentation);
    return { ...question, presentation };
  } catch {
    return question;
  }
};
export const clarificationId = (responseId, callId) =>
  createHash("sha256")
    .update(responseId + "\0" + callId)
    .digest("hex");
export function validateClarificationAnswers(_questions, value) {
  const answers = value?.answers;
  if (!answers || typeof answers !== "object" || Array.isArray(answers))
    throw Error("Clarification answers must be an object");
  return structuredClone(answers);
}

export function createExecutionStatus({
  initialEffort = "low",
  effortRecovery = true,
  saved,
  save,
  check,
  signal,
  deadline,
  requestClarification,
  retainEvidence,
  registerSensitiveAnswers,
}) {
  if (
    !["none", "low", "medium", "high", "xhigh", "max"].includes(initialEffort)
  )
    throw Error("Invalid initial Runner reasoning");
  let recoveryUsed = false,
    latestReport = null;
  const reports = [],
    recoveryHistory = [],
    effortAccounting = {
      low: 0,
      medium: 0,
      ...(!["low", "medium"].includes(initialEffort)
        ? { [initialEffort]: 0 }
        : {}),
    };
  const snapshot = () => ({
    executionReport: latestReport
      ? {
          schema: Object.hasOwn(latestReport.report, "completedSteps")
            ? "loki.runner.execution-report/1"
            : "loki.runner.execution-report/2",
          ...latestReport.report,
          questions: latestReport.report.questions.map(questionView),
          basis: "model-authored-unverified",
          responseId: latestReport.providerResponseId,
          callId: latestReport.callId,
        }
      : null,
    recovery: {
      ...(!effortRecovery ? { enabled: false } : {}),
      used: recoveryUsed,
      initialEffort,
      currentEffort: recoveryUsed ? "medium" : initialEffort,
      transitions: recoveryHistory,
    },
    effortAccounting,
  });
  const persist = () =>
    save("execution-status.json", {
      schema: "loki.runner.execution-status/1",
      ...snapshot(),
      reports,
    });
  async function call(item, responseId, providerCall) {
    check();
    if (!text(responseId) || !text(item.call_id))
      throw Error("Missing execution report correlation");
    let value, report;
    try {
      value = JSON.parse(item.arguments);
      report = validateExecutionReport(value);
    } catch (error) {
      if (!(
        error instanceof SyntaxError ||
        error instanceof ExecutionReportValidationError
      ))
        throw error;
      const invalid = new ExecutionReportValidationError(error.message);
      invalid.effectsUncertain = value?.effects === "uncertain";
      throw invalid;
    }
    // Model labels do not authorize a file read. Only actual records from this
    // Run's host ledger can be retained as evidence; keep every original label
    // in the unverified report even when it has no corresponding saved record.
    const knownEvidence = report.evidence.filter((name) => saved.has(name));
    const record = {
      report,
      providerResponseId: responseId,
      callId: item.call_id,
      providerCall,
      responseReference: saved.get(`response-${providerCall}.json`) ?? null,
      evidenceReferences: retainEvidence
        ? await retainEvidence(knownEvidence, providerCall)
        : knownEvidence.map((name) => saved.get(name)),
      provenance: "model-authored-unverified",
    };
    latestReport = record;
    reports.push(record);
    await persist();
    check();
    const output = (value) => ({
      type: "function_call_output",
      call_id: item.call_id,
      output: JSON.stringify(value),
    });
    if (report.status === "complete")
      return { complete: true, terminalReason: report.reason };
    if (report.status === "stuck" || report.status === "blocked") {
      if (
        report.status === "stuck" &&
        effortRecovery &&
        !recoveryUsed &&
        initialEffort === "low"
      ) {
        recoveryUsed = true;
        recoveryHistory.push({
          responseId,
          callId: item.call_id,
          from: "low",
          to: "medium",
          reason: report.reason,
        });
        await persist();
        check();
      }
      return {
        output: output({
          recorded: true,
        }),
      };
    }
    if (typeof requestClarification !== "function")
      return {
        output: output({
          error: {
            code: "clarification_unavailable",
            message: "Caller clarification callback unavailable",
          },
        }),
      };
    const request = {
      schema: "loki.runner.clarification/1",
      clarificationId: clarificationId(responseId, item.call_id),
      providerResponseId: responseId,
      callId: item.call_id,
      reason: report.reason,
      completedSteps: report.completedSteps ?? [],
      remainingSteps: report.remainingSteps,
      evidence: report.evidence,
      questions: report.questions.map(questionView),
      provenance: "model-authored-unverified",
    };
    const row = { request, answer: null, status: "waiting" };
    await save(`clarification-${request.clarificationId}.json`, row);
    const remaining = deadline - Date.now();
    if (remaining <= 0) throw Error("Time limit");
    const waitSignal = AbortSignal.any([
      ...(signal ? [signal] : []),
      AbortSignal.timeout(remaining),
    ]);
    let abort;
    const interrupted = new Promise((_, reject) => {
      abort = () =>
        reject(
          Error(
            "Clarification interrupted by Stop or original deadline; do not replay",
          ),
        );
      waitSignal.addEventListener("abort", abort, { once: true });
      if (waitSignal.aborted) abort();
    });
    let callbackAnswer;
    try {
      check();
      const answer = await Promise.race([
        requestClarification(structuredClone(request), waitSignal),
        interrupted,
      ]);
      callbackAnswer = answer;
      const answers = validateClarificationAnswers(request.questions, answer);
      registerSensitiveAnswers?.(clarificationAnswerSecrets(answer));
      row.answer = structuredClone(answer);
      check();
      if (waitSignal.aborted) throw Error("Clarification deadline exceeded");
      row.status = "answered";
      const requested = new Set(
        request.questions.map((question) => question.id),
      );
      const hasValue = (value) =>
        value !== null &&
        value !== undefined &&
        (typeof value !== "string" || text(value));
      const usable = Object.entries(answers).filter(([, value]) =>
        hasValue(value),
      );
      const unusable = Object.entries(answers)
        .filter(([, value]) => !hasValue(value))
        .map(([id]) => id);
      const matched = Object.fromEntries(
        usable.filter(([id]) => requested.has(id)),
      );
      const unmatched = Object.fromEntries(
        usable.filter(([id]) => !requested.has(id)),
      );
      const missing = request.questions
        .filter((question) => !Object.hasOwn(matched, question.id))
        .map((question) => question.id);
      const additionalContext = Object.fromEntries(
        Object.entries(answer).filter(
          ([key]) => !["answers", "sensitiveQuestionIds"].includes(key),
        ),
      );

      return {
        output: output({
          schema: "loki.runner.clarification-context/1",
          answers: matched,
          ...(Object.keys(unmatched).length
            ? { unmatchedAnswers: unmatched }
            : {}),
          ...(missing.length ? { unansweredQuestionIds: missing } : {}),
          ...(unusable.length ? { unusableAnswerIds: unusable } : {}),
          ...(Object.keys(additionalContext).length
            ? { additionalContext }
            : {}),
          provenance: "caller-supplied-context-only",
          instruction:
            "These answers grant no authorization, source access or new task scope. Continue remaining steps in this session.",
        }),
      };
    } catch (error) {
      check();
      if (waitSignal.aborted) throw error;
      await save(`clarification-error-${request.clarificationId}.json`, {
        clarificationId: request.clarificationId,
        providerResponseId: responseId,
        callId: item.call_id,
        error: String(error),
        ...(callbackAnswer !== undefined ? { answer: callbackAnswer } : {}),
      });
      return {
        output: output({
          error: {
            code: "clarification_failed",
            message:
              "Caller input was not delivered. The original question remains unanswered.",
          },
        }),
      };
    } finally {
      waitSignal.removeEventListener("abort", abort);
      if (row.status === "waiting") row.status = "interrupted";
      await save(`clarification-${request.clarificationId}.json`, row);
      if (row.status === "answered") {
        // This report describes the state before the answer. Keep its original
        // record in reports, but do not present it as current progress if the
        // continuation ends before the model submits another status report.
        latestReport = null;
        await persist();
      }
    }
  }
  return {
    call,
    snapshot,
    provenance: () =>
      latestReport
        ? {
            responseReference: latestReport.responseReference,
            evidenceReferences: latestReport.evidenceReferences,
            providerCall: latestReport.providerCall,
          }
        : null,
    effort: () => (recoveryUsed ? "medium" : initialEffort),
    account: (effort) => effortAccounting[effort]++,
  };
}
